import * as React from 'react';
import Svg, { Circle, Path } from 'react-native-svg';

// The icons of a message's action bar, in one hand: ChatGPT's own glyphs for
// copy, read aloud and branch — filled outlines on a 24 grid, a 2-unit line
// with round ends, each filling its canvas — and the bar's passing states,
// pause and queued, drawn to match.

type IconProps = { size: number; color: string };

function FilledIcon(props: IconProps & { d: string; evenOdd?: boolean }) {
    return (
        <Svg width={props.size} height={props.size} viewBox="0 0 24 24" fill="none">
            <Path
                d={props.d}
                fill={props.color}
                fillRule={props.evenOdd ? 'evenodd' : undefined}
                clipRule={props.evenOdd ? 'evenodd' : undefined}
            />
        </Svg>
    );
}

function StrokedIcon(props: IconProps & { children: React.ReactNode }) {
    return (
        <Svg
            width={props.size}
            height={props.size}
            viewBox="0 0 24 24"
            fill="none"
            stroke={props.color}
            strokeWidth={2}
            strokeLinecap="round"
            strokeLinejoin="round"
        >
            {props.children}
        </Svg>
    );
}

