// Two rounded sheets, the back one showing only where the front one leaves it.
export const CopyIcon = React.memo(function CopyIcon(props: IconProps) {
    return <FilledIcon {...props} d={COPY} />;
});

// A speaker with two sound waves.
export const SpeakerIcon = React.memo(function SpeakerIcon(props: IconProps) {
    return <FilledIcon {...props} d={SPEAKER} evenOdd />;
});

export const PauseIcon = React.memo(function PauseIcon(props: IconProps) {
    return (
        <StrokedIcon {...props}>
            <Path d="M8 3V21M16 3V21" />
        </StrokedIcon>
    );
});

export const ClockIcon = React.memo(function ClockIcon(props: IconProps) {
    return (
        <StrokedIcon {...props}>
            <Circle cx={12} cy={12} r={9.5} />
            <Path d="M12 7V12H16" />
        </StrokedIcon>
    );
});

// A line from the left that bends up-right into an arrow, with a second arrow
// leaving the bend down-right — "go on from here in a new session".
export const ForkIcon = React.memo(function ForkIcon(props: IconProps) {
    return <FilledIcon {...props} d={FORK} />;
});
